   681          remain_len += props_len = MqttEncode_Props(MQTT_PACKET_TYPE_CONNECT,
   682                  mc_connect->props, NULL);
   683
   684          /* Determine the length of the "property length" */
   685          remain_len += MqttEncode_Vbi(NULL, props_len);
   686      }
