   694              (mc_connect->lwt_msg->buffer == NULL &&
   695               mc_connect->lwt_msg->total_len != 0))
   696          {
   697              return MQTT_TRACE_ERROR(MQTT_CODE_ERROR_BAD_ARG);
   698          }
   699
   700          remain_len += (int)XSTRLEN(mc_connect->lwt_msg->topic_name);
   701          remain_len += MQTT_DATA_LEN_SIZE;
   702          remain_len += mc_connect->lwt_msg->total_len;
   703          remain_len += MQTT_DATA_LEN_SIZE;
   704  #ifdef WOLFMQTT_V5
   705      if (mc_connect->protocol_level >= MQTT_CONNECT_PROTOCOL_LEVEL_5) {
   706          /* Determine length of properties */
   707          remain_len += lwt_props_len = MqttEncode_Props(MQTT_PACKET_TYPE_CONNECT,
   708                  mc_connect->lwt_msg->props, NULL);
   709
   710          /* Determine the length of the "lwt property length" */
   711          remain_len += MqttEncode_Vbi(NULL, lwt_props_len);
   712      }
   713  #endif
   714      }
   715      if (mc_connect->username) {
   716          remain_len += (int)XSTRLEN(mc_connect->username) + MQTT_DATA_LEN_SIZE;
   717      }
   718      if (mc_connect->password) {
   719          remain_len += (int)XSTRLEN(mc_connect->password) + MQTT_DATA_LEN_SIZE;
   720      }
