   723      header_len = MqttEncode_FixedHeader(tx_buf, tx_buf_len, remain_len,
   724          MQTT_PACKET_TYPE_CONNECT, 0, 0, 0);
   725      if (header_len < 0) {
   726          return header_len;
   727      }
   728      /* Check for buffer room */
   729      if (tx_buf_len < header_len + remain_len) {
   730          return MQTT_TRACE_ERROR(MQTT_CODE_ERROR_OUT_OF_BUFFER);
   731      }
