   748              packet.flags |= MQTT_CONNECT_FLAG_SET_QOS(mc_connect->lwt_msg->qos);
   749          }
   750          if (mc_connect->lwt_msg->retain) {
   751              packet.flags |= MQTT_CONNECT_FLAG_WILL_RETAIN;
   752          }
   753      }
   754      if (mc_connect->username) {
   755          packet.flags |= MQTT_CONNECT_FLAG_USERNAME;
   756      }
   757      if (mc_connect->password) {
   758          packet.flags |= MQTT_CONNECT_FLAG_PASSWORD;
   759      }
